package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.BeanProperty;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.deser.std.NullifyingDeserializer;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeIdResolver;
import com.fasterxml.jackson.databind.node.JsonNodeFactory;
import com.fasterxml.jackson.databind.type.JavaType;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.*;
import static org.mockito.Mockito.*;

public class TypeDeserializerBase__findDeserializer_TriageGen1Test {

    private TestableTypeDeserializerBase deserializerBase;
    private DeserializationContext ctxt;
    private TypeIdResolver idResolver;
    private JavaType baseType;
    private BeanProperty property;
    private Map<String, JsonDeserializer<Object>> deserializersMap;

    // Concrete implementation to test protected method
    private static class TestableTypeDeserializerBase extends TypeDeserializerBase {
        protected Map<String, JsonDeserializer<Object>> _deserializers = new HashMap<>();
        protected JavaType _baseType;
        protected BeanProperty _property;

        protected TestableTypeDeserializerBase(JavaType baseType, TypeIdResolver idRes, String typePropertyName, 
                                              boolean typeIdVisible, JavaType defaultImpl, BeanProperty property) {
            super(baseType, idRes, typePropertyName, typeIdVisible, defaultImpl);
            this._baseType = baseType;
            this._property = property;
        }

        @Override
        public TypeDeserializer forProperty(BeanProperty prop) { return null; }
        @Override
        public JsonTypeInfo.As getTypeInclusion() { return null; }
        @Override
        public String baseTypeName() { return "test"; }

        // Expose protected method for testing
        @Override
        protected final JsonDeserializer<Object> _findDeserializer(DeserializationContext ctxt, String typeId) throws IOException {
            return super._findDeserializer(ctxt, typeId);
        }

        // Override to access internal field for testing
        public void setDeserializers(Map<String, JsonDeserializer<Object>> map) {
            this._deserializers = map;
        }

        // Helper to inject the internal map via reflection or shadowing if necessary, 
        // but here we use the member variable directly as the class is designed for testing.
        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return super._findDefaultImplDeserializer(ctxt);
        }
    }

    // Subclass to override protected/abstract methods for mocking
    private static class MockableTypeDeserializerBase extends TestableTypeDeserializerBase {
        private JsonDeserializer<Object> mockDefaultDeser;
        private JavaType mockHandleResult;

        protected MockableTypeDeserializerBase(JavaType baseType, TypeIdResolver idRes, BeanProperty property) {
            super(baseType, idRes, "type", true, null, property);
        }

        @Override
        protected JsonDeserializer<Object> _findDefaultImplDeserializer(DeserializationContext ctxt) throws IOException {
            return mockDefaultDeser;
        }

        @Override
        protected JavaType _handleUnknownTypeId(DeserializationContext ctxt, String typeId, TypeIdResolver idResolver, JavaType baseType) throws IOException {
            return mockHandleResult;
        }
    }

    @Before
    public void setup() {
        ctxt = mock(DeserializationContext.class);
        idResolver = mock(TypeIdResolver.class);
        baseType = TypeFactory.defaultInstance().constructType(Object.class);
        property = mock(BeanProperty.class);
        deserializersMap = new HashMap<>();

        when(ctxt.getTypeFactory()).thenReturn(TypeFactory.defaultInstance());

        deserializerBase = new MockableTypeDeserializerBase(baseType, idResolver, property);
        ((MockableTypeDeserializerBase) deserializerBase).setDeserializers(deserializersMap);
    }

    @Test
    public void testFindDeserializer_AlreadyExists() throws IOException {
        JsonDeserializer<Object> existing = mock(JsonDeserializer.class);
        deserializersMap.put("existingId", existing);

        JsonDeserializer<Object> result = deserializerBase._findDeserializer(ctxt, "existingId");

        assertEquals(existing, result);
        verifyNoInteractions(idResolver);
    }

    @Test
    public void testFindDeserializer_ViaIdResolver_Success() throws IOException {
        String typeId = "myType";
        JavaType type = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(ctxt.findContextualValueDeserializer(eq(type), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = deserializerBase._findDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
        assertEquals(expectedDeser, deserializersMap.get(typeId));
    }

    @Test
    public void testFindDeserializer_ViaDefaultImpl_Success() throws IOException {
        String typeId = "unknownId";
        JsonDeserializer<Object> defaultDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        ((MockableTypeDeserializerBase) deserializerBase).mockDefaultDeser = defaultDeser;

        JsonDeserializer<Object> result = deserializerBase._findDeserializer(ctxt, typeId);

        assertEquals(defaultDeser, result);
        assertEquals(defaultDeser, deserializersMap.get(typeId));
    }

    @Test
    public void testFindDeserializer_ViaHandleUnknownTypeId_Success() throws IOException {
        String typeId = "unknownId";
        JavaType actualType = TypeFactory.defaultInstance().constructType(Integer.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        ((MockableTypeDeserializerBase) deserializerBase).mockDefaultDeser = null;
        ((MockableTypeDeserializerBase) deserializerBase).mockHandleResult = actualType;
        when(ctxt.findContextualValueDeserializer(eq(actualType), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = deserializerBase._findDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
        assertEquals(expectedDeser, deserializersMap.get(typeId));
    }

    @Test
    public void testFindDeserializer_ReturnsNullWhenAllFail() throws IOException {
        String typeId = "unknownId";
        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(null);
        ((MockableTypeDeserializerBase) deserializerBase).mockDefaultDeser = null;
        ((MockableTypeDeserializerBase) deserializerBase).mockHandleResult = null;

        JsonDeserializer<Object> result = deserializerBase._findDeserializer(ctxt, typeId);

        assertNull(result);
    }

    @Test
    public void testFindDeserializer_WithSpecializedType() throws IOException {
        String typeId = "specialType";
        // Mock base type as a Map to trigger the specialized type logic
        JavaType mapBaseType = TypeFactory.defaultInstance().constructMapType(Map.class, Object.class, Object.class);

        MockableTypeDeserializerBase complexBase = new MockableTypeDeserializerBase(mapBaseType, idResolver, property);
        complexBase.setDeserializers(deserializersMap);

        JavaType nominalType = TypeFactory.defaultInstance().constructType(Map.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(nominalType);
        // The code checks if baseType.getClass() == type.getClass(). 
        // Since both are likely BeanProperty or internal Jackson types, we ensure the branch is hit.
        // Note: type.getRawClass() for Map.class is Map.class.

        // We need to mock findContextualValueDeserializer to accept the specialized type
        // Because constructSpecializedType returns a new instance, we use any() or capture
        when(ctxt.findContextualValueDeserializer(any(JavaType.class), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = complexBase._findDeserializer(ctxt, typeId);

        assertNotNull(result);
        assertEquals(expectedDeser, result);
        verify(ctxt).findContextualValueDeserializer(argThat(t -> t.getRawClass().equals(Map.class)), eq(property));
    }

    @Test
    public void testFindDeserializer_BaseTypeNull_SkipsSpecialization() throws IOException {
        String typeId = "noBaseType";
        MockableTypeDeserializerBase nullBase = new MockableTypeDeserializerBase(null, idResolver, property);
        nullBase.setDeserializers(deserializersMap);

        JavaType type = TypeFactory.defaultInstance().constructType(String.class);
        JsonDeserializer<Object> expectedDeser = mock(JsonDeserializer.class);

        when(idResolver.typeFromId(ctxt, typeId)).thenReturn(type);
        when(ctxt.findContextualValueDeserializer(eq(type), any())).thenReturn(expectedDeser);

        JsonDeserializer<Object> result = nullBase._findDeserializer(ctxt, typeId);

        assertEquals(expectedDeser, result);
    }
}
